/// One branch of the ring, in store order (tree by tree, Production / Network / State). The
/// research panel labels and its angular layout read this; nothing in the sim does.
struct branch_info
{
    const char* key;       ///< "PR-EX" etc.; what `node::branch` names.
    const char* name;      ///< "Extraction".
    const char* tree;      ///< "PR".
    const char* tree_name; ///< "Production".
};

